import {parse,resolve,money,schedule} from './parser.mjs';
const $=id=>document.getElementById(id), currency=n=>new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(n/100), key='miudo-records-v1';
let records=[],pending=null,editing=null;
try{const stored=JSON.parse(localStorage.getItem(key)||'[]'); if(Array.isArray(stored)) records=stored.filter(r=>typeof r.id==='string'&&typeof r.description==='string'&&Number.isSafeInteger(r.amount)&&r.amount>0&&['despesa','receita'].includes(r.type)&&typeof r.category==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(r.date)&&Number.isInteger(r.installments)&&r.installments>=1&&r.installments<=120);}catch{}
const icons={'Alimentação':'🥖','Transporte':'↗','Casa':'⌂','Saúde':'✚','Outros':'▧','Receitas':'↙'};
function el(tag,cls,text){const node=document.createElement(tag);if(cls)node.className=cls;if(text!==undefined)node.textContent=text;return node;}
function button(label,fn){const b=el('button','',label);b.type='button';b.addEventListener('click',fn);return b;}
function persist(){try{localStorage.setItem(key,JSON.stringify(records));}catch{bubble('Não foi possível salvar neste navegador. Exporte os lançamentos para guardá-los.');}render();}
function render(){const income=records.filter(r=>r.type==='receita').reduce((s,r)=>s+r.amount,0), expense=records.filter(r=>r.type==='despesa').reduce((s,r)=>s+r.amount,0);$('income').textContent=currency(income);$('expense').textContent=currency(expense);$('balance').textContent=currency(income-expense);$('count').textContent=records.length;$('records').replaceChildren();$('export').disabled=$('clear').disabled=!records.length;
 if(!records.length){const empty=el('div','empty');empty.append(el('span','empty-icon','↗'),el('strong','','O primeiro lançamento começa com você.'),el('p','','Mande uma mensagem ao lado e veja suas finanças ganharem forma.'));$('records').append(empty);}
 for(const r of [...records].reverse()){const row=el('div','record'),main=el('div','record-main'),value=el('div','record-value');main.append(el('strong','',r.description),el('small','',`${r.category} · ${r.date.split('-').reverse().join('/')} ${r.installments>1?`· ${r.installments} parcelas`:''}`));const edit=button('Editar',()=>openEdit(r.id));edit.className='text-btn';value.append(el('strong','',`${r.type==='receita'?'+':'−'} ${currency(r.amount)}`),edit);row.append(el('span','record-icon',icons[r.category]||'▧'),main,value);$('records').append(row);}}
function bubble(text,user=false,actions=[]){const node=el('div',`bubble ${user?'user':'bot'}`,text);if(actions.length){const bar=el('div','message-actions');for(const a of actions)bar.append(button(a.label,a.fn));node.append(bar);}node.append(el('span','stamp',user?'Você':'Miúdo'));$('messages').append(node);$('messages').scrollTop=$('messages').scrollHeight;return node;}
function remove(id,node){if(!records.some(r=>r.id===id))return;records=records.filter(r=>r.id!==id);persist();if(node)node.querySelectorAll('button').forEach(b=>b.disabled=true);bubble('Lançamento desfeito.');}
function commit(result){const record={...result,id:crypto.randomUUID()};delete record.question;delete record.status;record.schedule=schedule(record);records.push(record);persist();pending=null;let node;node=bubble(`✓ ${record.type==='receita'?'Entrada registrada':'Despesa registrada'}: ${currency(record.amount)} em ${record.description}.\n${record.category} · ${record.date.split('-').reverse().join('/')}${record.installments>1?` · ${record.installments} parcelas (primeira: ${currency(record.schedule[0].amount)})`:''}` ,false,[{label:'Editar',fn:()=>openEdit(record.id)},{label:'Desfazer',fn:()=>remove(record.id,node)}]);}
function send(text){text=text.trim();if(!text)return;bubble(text,true);$('message').value='';if(pending){if(/^cancelar$/i.test(text)){pending=null;bubble('Tudo bem, lançamento cancelado.');return;}const answer=resolve(pending,text);if(answer.status==='ready')commit(answer);else bubble(answer.question);return;}
 const result=parse(text);if(result.status==='ready')commit(result);else if(['missing_amount','ambiguous'].includes(result.status)){pending=result;bubble(result.question,false,[{label:'Cancelar',fn:()=>{if(pending!==result)return;pending=null;bubble('Lançamento cancelado. Pode enviar outra mensagem.');}}]);}else bubble(result.question);}
$('message-form').addEventListener('submit',e=>{e.preventDefault();send($('message').value);$('message').focus();});document.querySelectorAll('[data-example]').forEach(b=>b.addEventListener('click',()=>{if(pending){bubble('Responda o valor solicitado ou cancele o lançamento atual para testar outro exemplo.');return;}send(b.dataset.example);$('message').focus();}));
function openEdit(id){const r=records.find(r=>r.id===id);if(!r){bubble('Esse lançamento já foi desfeito.');return;}editing=id;$('edit-description').value=r.description;$('edit-amount').value=(r.amount/100).toFixed(2).replace('.',',');$('edit-type').value=r.type;$('edit-category').value=r.category;$('edit-date').value=r.date;$('edit-installments').value=r.installments;$('edit-error').textContent='';$('edit-dialog').showModal();}
$('close-dialog').addEventListener('click',()=>$('edit-dialog').close());$('edit-form').addEventListener('submit',e=>{e.preventDefault();const amount=money($('edit-amount').value.trim()), description=$('edit-description').value.trim(), installments=Number($('edit-installments').value);if(!amount||!description||!Number.isInteger(installments)||installments<1||installments>120){$('edit-error').textContent='Confira o valor, a descrição e o número de parcelas.';return;}const r=records.find(r=>r.id===editing);if(r){Object.assign(r,{amount,description,installments,date:$('edit-date').value,type:$('edit-type').value,category:$('edit-category').value});r.schedule=schedule(r);persist();bubble(`Lançamento atualizado: ${r.description} · ${currency(r.amount)}.`);}$('edit-dialog').close();});
$('clear').addEventListener('click',()=>$('clear-dialog').showModal());$('cancel-clear').addEventListener('click',()=>$('clear-dialog').close());$('confirm-clear').addEventListener('click',()=>{records=[];pending=null;persist();$('clear-dialog').close();$('messages').querySelectorAll('.message-actions button').forEach(b=>b.disabled=true);bubble('Dados apagados. Vamos começar de novo?');});
$('export').addEventListener('click',()=>{const cell=value=>'"'+String(value).replace(/^[=+@\-]/,"'$&").replaceAll('"','""')+'"';const rows=[['Descrição','Tipo','Valor total (BRL)','Categoria','Data','Parcelas'],...records.map(r=>[r.description,r.type,(r.amount/100).toFixed(2).replace('.',','),r.category,r.date,r.installments])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(cell).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'});const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='miudo-lancamentos.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);});
render();
